fn transfer(v: Vec[Int]) -> Vec[Int] {
  return v;
}

fn main() -> Int {
  let v1 = Vec[Int]();
  v1.push(10);
  v1.push(20);
  v1.push(30);
  let v2 = transfer(v1);
  var sum = 0;
  var i = 0;
  while i < v2.len() {
    sum = sum + v2[i];
    i = i + 1;
  }
  return sum;
}
